async function loadInOrder(ids, fetchOne) {
  const values = [];
  for (const id of ids) values.push(await fetchOne(id));
  return values;
}

async function loadAll(ids, fetchOne) {
  return Promise.all(ids.map(id => fetchOne(id)));
}

async function loadSafely(ids, fetchOne) {
  const outcomes = await Promise.allSettled(ids.map(id => fetchOne(id)));
  const loaded = [], failed = [];
  outcomes.forEach((o, i) => (o.status === "fulfilled" ? loaded.push(o.value) : failed.push(ids[i])));
  return { loaded, failed };
}

