function tracker() {
  const t = { active: 0, peak: 0 };
  t.fetchOne = async id => {
    t.active++;
    t.peak = Math.max(t.peak, t.active);
    await new Promise(r => setTimeout(r, 30 - id * 5));
    t.active--;
    if (id < 0) throw new Error(`bad id ${id}`);
    return `item${id}`;
  };
  return t;
}

test("in order, one at a time", async () => {
  const t = tracker();
  checkEq(await loadInOrder([1, 2, 3], t.fetchOne), ["item1", "item2", "item3"]);
  checkEq(t.peak, 1);
  checkEq(await loadInOrder([], t.fetchOne), []);
});

test("all at once, results in order", async () => {
  const t = tracker();
  checkEq(await loadAll([1, 2, 3, 4], t.fetchOne), ["item1", "item2", "item3", "item4"]);
  checkEq(t.peak, 4);
});

test("errors reject", async () => {
  const t = tracker();
  try { await loadInOrder([1, -1, 2], t.fetchOne); check(false, "should reject"); }
  catch (e) { checkEq(e.message, "bad id -1"); }
  try { await loadAll([1, -2], t.fetchOne); check(false, "should reject"); }
  catch (e) { checkEq(e.message, "bad id -2"); }
});

test("safe loading", async () => {
  const t = tracker();
  checkEq(await loadSafely([1, -1, 2, -3], t.fetchOne), { loaded: ["item1", "item2"], failed: [-1, -3] });
  checkEq(t.peak, 4);
});

